/**
 * @description ShaderManagerのブレンドモードののuniform変数を設定します。
 *              Set the uniform variable of the blend mode of ShaderManager.
 *
 * @param  {ShaderManager} shader_manager
 * @param  {number} ct0
 * @param  {number} ct1
 * @param  {number} ct2
 * @param  {number} ct3
 * @param  {number} ct4
 * @param  {number} ct5
 * @param  {number} ct6
 * @param  {number} ct7
 * @return {void}
 * @method
 * @protected
 */
export const execute = (shader_manager, ct0, ct1, ct2, ct3, ct4, ct5, ct6, ct7) => {
    const textures = shader_manager.textures;
    textures[0] = 0;
    textures[1] = 1;
    const mediump = shader_manager.mediump;
    // fragment: u_color_transform_mul
    mediump[0] = ct0;
    mediump[1] = ct1;
    mediump[2] = ct2;
    mediump[3] = ct3;
    // fragment: u_color_transform_add
    mediump[4] = ct4;
    mediump[5] = ct5;
    mediump[6] = ct6;
    mediump[7] = ct7;
};
